static void sortProducts(List<Product> products, String criteria) {
    Comparator<Product> comparator = switch (criteria) {
        case "price_asc" -> Comparator.comparingDouble(Product::getPrice);
        case "rating_desc" -> Comparator.comparingDouble(Product::getRating).reversed();
        case "name" -> Comparator.comparing(Product::getName);
        default -> throw new IllegalArgumentException("Nieznane kryterium: " + criteria);
    };
    products.sort(comparator);
}

public static void main(String[] args) {
    List<Product> products = new ArrayList<>(List.of(
        new Product("B", "cat", 100, 4.5), new Product("A", "cat", 50, 4.9)
    ));
    sortProducts(products, "price_asc");
    System.out.println(products);
}

